pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);
        vm.deal(alice, 10 ether);
        vm.deal(bob, 5 ether);
        vm.prank(alice);
        c.deposit{value: 10 ether}();
        vm.prank(bob);
        c.deposit{value: 5 ether}();
        vm.prank(alice);
        c.withdraw();
        assertTrue(c.balances(alice) == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.fallback{value: 1 ether}();
        vm.prank(alice);
        c.withdraw();
        assertTrue(address(c).balance == 0 ether);
    }
}
